import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import "../styles/Academics.css";

export default function Academics() {
  const [data, setData] = useState({});

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/academics")
      .then((res) => {
        setData(res.data || {});
        toast.success("Data loaded successfully!"); // ✅ success toast
      })
      .catch((err) => {
        toast.error("Failed to load data"); // ❌ error toast
        console.error(err);
      });
  }, []);

  const decodeHTML = (str) => {
    const textarea = document.createElement("textarea");
    textarea.innerHTML = str;
    return textarea.value;
  };

  return (
    <div className="academics-page">
      <Toaster /> {/* 🔹 Toast container */}
      <h1 className="academics-title">Academics</h1>

      {Object.entries(data).map(([section, html]) => (
        <div key={section} className="academics-section">
          <h2 className="section-title">
            {section.charAt(0).toUpperCase() + section.slice(1)}
          </h2>

          <div
            className="ql-editor academics-content"
            dangerouslySetInnerHTML={{ __html: decodeHTML(html) }}
          ></div>
        </div>
      ))}
    </div>
  );
}
